from ui_styles_ore_ini import ringfill
from ui_styles_voice import flat
import numpy as np
STYLES = {}

def win(style, c0, c1):
    def cut(ink, base):
        art, b = style(ink, base)
        out = art[:, c0:c1]
        if out.shape[1] == 0:
            out = np.zeros((art.shape[0], 1), np.uint8)
        return out, b
    return cut

